-- Generated by tools/build_quest_data.py; references are not eligibility or a walkthrough.
return {["scripts/quests/otherAreas/helpers.lua"]={["Path"]="scripts/quests/otherAreas/helpers.lua",["SHA256"]="dfa7720a44eccd5984aacb66f1eafb33979758926420c8aa00d395270ca11fca",["Text"]="-----------------------------------\n-- Helpers for otherAreas quests\n-----------------------------------\nlocal davoiID = zones[xi.zone.DAVOI]\n-----------------------------------\nxi = xi or {}\nxi.otherAreas = xi.otherAreas or {}\nxi.otherAreas.helpers = xi.otherAreas.helpers or {}\nxi.otherAreas.helpers.TestMyMettle = {}\n\nfunction xi.otherAreas.helpers.TestMyMettle.moveJar(npc)\n    -- 5 min (offset by onGameHour frequency of ~2.5 min) to 3 hours\n    -- full equation = ((2.5 * 10) * 6) to ((3 * 60) * 60)\n    local randomHourSpan = math.randomInt(125, 10800)\n\n    SetServerVariable('Davoi_Jar_Move_Time', GetSystemTime() + randomHourSpan)\n\n    local positions =\n    {\n        {  185.230, -0.865, -189.750 }, -- [0] J-9 Jar near campfire\n        {   94.290, -8.450, -163.800 }, -- [1] I-8 Jar near lake\n        {  275.770,  3.160, -204.120 }, -- [2] K-9 Jar near stump\n        {  171.750, -3.300, -111.800 }, -- [3] J-8 Jar on platform\n        {   58.300, -9.780, -132.430 }, -- [4] H-8 Jar near oak door\n        {   25.080,  0.440, -107.300 }, -- [5] H-8 Jar near campfire\n        { -106.770,  2.580,   26.060 }, -- [6] F-6 Jar north of Hut Flap\n        { -128.720,  3.250, -237.600 }, -- [7] F-9 Jar near stump\n        {  -36.720,  3.300, -218.270 }, -- [8] G-9 Jar near well\n        {   54.800,  0.720, -202.950 }, -- [9] H-9 Jar near campfire\n    }\n\n    local newPosition = npcUtil.pickNewPosition(davoiID.npc.JAR, positions, false)\n\n    npcUtil.queueMove(npc, newPosition)\nend\n"},["scripts/quests/outlands/A_Question_of_Taste.lua"]={["Path"]="scripts/quests/outlands/A_Question_of_Taste.lua",["SHA256"]="b069e2c5f01b68fd4eaf2dc632dae58716d08fa1e740d1ccdd877cf80b6c6d8b",["Text"]="-----------------------------------\n-- A Question of Taste\n-- Log ID: 5, Quest ID: 3\n-- Etteh_Sulaej        !pos 98.153 -15.000 -113.251\n-- Angelica            !pos -64 -9.25 -9\n-- Stone Picture Frame !pos 79.876 0.500 -36.964\n-----------------------------------\nlocal templeID = zones[xi.zone.TEMPLE_OF_UGGALEPIH]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OUTLANDS, xi.quest.id.outlands.A_QUESTION_OF_TASTE)\n\nquest.reward =\n{\n    gil = 3000,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getFameLevel(xi.fameArea.WINDURST) >= 6\n        end,\n\n        [xi.zone.KAZHAM] =\n        {\n            ['Etteh_Sulaej'] = quest:progressCutscene(44),\n\n            onEventFinish =\n            {\n                [44] = function(player, csid, option, npc)\n                    quest:begin(player)\n                    npcUtil.giveKeyItem(player, xi.keyItem.LETTER_TO_ANGELICA)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.KAZHAM] =\n        {\n            ['Etteh_Sulaej'] =\n            {\n                onTrigger = function(player, npc)\n                    local progress = quest:getVar(player, 'Prog')\n\n                    if progress == 1 then\n                        return quest:progressEvent(47)\n                    elseif progress == 4 then\n                        return quest:progressEvent(50)\n                    elseif progress >= 2 then\n                        return quest:event(49)\n                    else\n                        return quest:event(45)\n                    end\n                end,\n            },\n\n            ['Jakoh_Wahcondalo'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') >= 2 then\n                        return quest:event(48)\n                    else\n                        return quest:event(46)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [47] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                    player:delKeyItem(xi.keyItem.ANGELICAS_LETTER)\n                end,\n\n                [50] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:addFame(xi.fameArea.WINDURST, 16)\n                        player:delKeyItem(xi.keyItem.RIPPED_FINAL_FANTASY_PAINTING)\n                        quest:setMustZone(player)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.TEMPLE_OF_UGGALEPIH] =\n        {\n            ['Stone_Picture_Frame_QoT'] =\n            {\n                onTrigger = function(player, npc)\n                    local progress = quest:getVar(player, 'Prog')\n                    local questNM  = GetMobByID(templeID.mob.TROMPE_LOEIL)\n\n                    if progress == 2 then\n                        if quest:getVar(player, 'Wait') > GetSystemTime() then\n                            player:messageSpecial(templeID.text.FRAME_FOR_A_PAINTING + 1)\n                            return quest:messageSpecial(templeID.text.STILL_HANGS_ON_THE_WALL, xi.keyItem.RIPPED_FINAL_FANTASY_PAINTING)\n                        elseif not questNM then\n                            return\n                        elseif not questNM:isSpawned() then\n                            return quest:progressEvent(50, xi.keyItem.FINAL_FANTASY)\n                        end\n                    elseif progress == 3 then\n                        npcUtil.giveKeyItem(player, xi.keyItem.RIPPED_FINAL_FANTASY_PAINTING)\n                        quest:setVar(player, 'Prog', 4)\n                        return quest:noAction()\n                    end\n                end,\n            },\n\n            ['Trompe_LOeil'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if quest:getVar(player, 'Prog') == 2 then\n                        quest:setVar(player, 'Prog', 3)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [50] = function(player, csid, option, npc)\n                    if option == 1 then\n                        player:delKeyItem(xi.keyItem.FINAL_FANTASY)\n                        SpawnMob(templeID.mob.TROMPE_LOEIL):updateClaim(player)\n                        quest:setVar(player, 'Wait', GetSystemTime() + 900) -- Sets a 15min cooldown before the player can repop the NM.\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Angelica'] =\n            {\n                onTrigger = function(player, npc)\n                    local progress = quest:getVar(player, 'Prog')\n\n                    if\n                        player:hasCompletedQuest(xi.questLog.WINDURST, xi.quest.id.windurst.A_POSE_BY_ANY_OTHER_NAME) and\n                        not xi.quest.getMustZone(player, xi.questLog.WINDURST, xi.quest.id.windurst.A_POSE_BY_ANY_OTHER_NAME)\n                    then\n                        if progress == 0 then\n                            return quest:progressEvent(771)\n                        else\n                            return quest:event(772)\n                        end\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [771] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                    npcUtil.giveKeyItem(player, xi.keyItem.FINAL_FANTASY)\n                    npcUtil.giveKeyItem(player, xi.keyItem.ANGELICAS_LETTER)\n                    player:delKeyItem(xi.keyItem.LETTER_TO_ANGELICA)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.KAZHAM] =\n        {\n            ['Etteh_Sulaej'] =\n            {\n                onTrigger = function(player, npc)\n                    local progress = quest:getVar(player, 'Prog')\n\n                    if quest:getMustZone(player) then\n                        return quest:event(51)\n                    elseif\n                        -- The player cannot do the repeat if they meet the requirements for \"Everyone's Grudging\"\n                        player:getCharVar('rancorCurse') == 1 and\n                        player:getFameLevel(xi.fameArea.WINDURST) >= 7 and\n                        not player:hasCompletedQuest(xi.questLog.OUTLANDS, xi.quest.id.outlands.EVERYONES_GRUDGING)\n                    then\n                        return -- Sends to default action as seen in captures\n                    else\n                        if progress == 3 then\n                            return quest:progressEvent(57)\n                        elseif progress >= 1 then\n                            return quest:event(55)\n                        else\n                            if quest:getVar(player, 'Option') == 0 then\n                                return quest:progressEvent(53)\n                            else\n                                return quest:progressEvent(54)\n                            end\n                        end\n                    end\n                end,\n            },\n\n            ['Jakoh_Wahcondalo'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getMustZone(player) then\n                        return quest:event(52)\n                    elseif quest:getVar(player, 'Prog') >= 1 then\n                        return quest:event(56)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [53] = function(player, csid, option, npc)\n                    if option == 2 then\n                        quest:setVar(player, 'Option', 1)\n                    else\n                        quest:setVar(player, 'Prog', 1)\n                        quest:begin(player)\n                        npcUtil.giveKeyItem(player, xi.keyItem.FINAL_FANTASY_PART_II)\n                    end\n                end,\n\n                [54] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:setVar(player, 'Prog', 1)\n                        quest:begin(player)\n                        npcUtil.giveKeyItem(player, xi.keyItem.FINAL_FANTASY_PART_II)\n                    end\n                end,\n\n                [57] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:addFame(xi.fameArea.WINDURST, 16)\n                        player:delKeyItem(xi.keyItem.RIPPED_FINAL_FANTASY_PAINTING)\n                        quest:setMustZone(player)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.TEMPLE_OF_UGGALEPIH] =\n        {\n            ['Stone_Picture_Frame_QoT'] =\n            {\n                onTrigger = function(player, npc)\n                    local progress = quest:getVar(player, 'Prog')\n                    local questNM  = GetMobByID(templeID.mob.TROMPE_LOEIL)\n\n                    if progress == 1 then\n                        if quest:getVar(player, 'Wait') > GetSystemTime() then\n                            player:messageSpecial(templeID.text.FRAME_FOR_A_PAINTING + 1)\n                            return quest:messageSpecial(templeID.text.STILL_HANGS_ON_THE_WALL, xi.keyItem.RIPPED_FINAL_FANTASY_PAINTING)\n                        elseif not questNM then\n                            return\n                        elseif not questNM:isSpawned() then\n                            return quest:progressEvent(51, xi.keyItem.FINAL_FANTASY_PART_II)\n                        end\n                    elseif progress == 2 then\n                        npcUtil.giveKeyItem(player, xi.keyItem.RIPPED_FINAL_FANTASY_PAINTING)\n                        quest:setVar(player, 'Prog', 3)\n                        return quest:noAction()\n                    end\n                end,\n            },\n\n            ['Trompe_LOeil'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        quest:setVar(player, 'Prog', 2)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [51] = function(player, csid, option, npc)\n                    if option == 1 then\n                        player:delKeyItem(xi.keyItem.FINAL_FANTASY_PART_II)\n                        SpawnMob(templeID.mob.TROMPE_LOEIL):updateClaim(player)\n                        quest:setVar(player, 'Wait', GetSystemTime() + 900) -- Sets a 15min cooldown before the player can repop the NM.\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Angelica'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:event(772)\n                    else\n                        return quest:event(773):replaceDefault()\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/outlands/Bugi_Soden.lua"]={["Path"]="scripts/quests/outlands/Bugi_Soden.lua",["SHA256"]="75a1c79205ae76816afaa7cee1b45f29bfd79def162abc1cddc3aef22ed57462",["Text"]="-----------------------------------\n-- Bugi Soden\n-- Ryoma !pos -23 0 -9 252\n-- qm1 !pos 110 15 162 213\n-----------------------------------\nlocal norgID   = zones[xi.zone.NORG]\nlocal onzozoID = zones[xi.zone.LABYRINTH_OF_ONZOZO]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OUTLANDS, xi.quest.id.outlands.BUGI_SODEN)\n\nquest.reward =\n{\n    fame = 20,\n    fameArea = xi.fameArea.NORG,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:canEquipItem(xi.item.KODACHI_OF_TRIALS, true) and\n                player:getCharSkillLevel(xi.skill.KATANA) / 10 >= 250 and\n                not player:hasKeyItem(xi.keyItem.WEAPON_TRAINING_GUIDE)\n        end,\n\n        [xi.zone.NORG] =\n        {\n            ['Ryoma'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(184):oncePerZone() -- start\n                end,\n            },\n\n            onEventFinish =\n            {\n                [184] = function(player, csid, option, npc)\n                    if\n                        option == 1 and\n                        (player:hasItem(xi.item.KODACHI_OF_TRIALS) or npcUtil.giveItem(player, xi.item.KODACHI_OF_TRIALS))\n                    then\n                        npcUtil.giveKeyItem(player, xi.keyItem.WEAPON_TRAINING_GUIDE)\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.NORG] =\n        {\n            ['Ryoma'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.ANNALS_OF_TRUTH) then\n                        return quest:progressEvent(189) -- complete\n                    elseif player:hasKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH) then\n                        return quest:event(188) -- cont 2\n                    else\n                        return quest:event(185) -- cont 1\n                    end\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, xi.item.KODACHI_OF_TRIALS) then\n                        local wsPoints = trade:getItem(0):getWeaponskillPoints()\n\n                        if wsPoints < 300 then\n                            return quest:event(186) -- unfinished weapon\n                        else\n                            return quest:progressEvent(187) -- finished weapon\n                        end\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [185] = function(player, csid, option, npc)\n                    if option == 2 then\n                        player:delQuest(xi.questLog.OUTLANDS, xi.quest.id.outlands.BUGI_SODEN)\n                        player:delKeyItem(xi.keyItem.WEAPON_TRAINING_GUIDE)\n                        player:delKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH)\n                    elseif not player:hasItem(xi.item.KODACHI_OF_TRIALS) then\n                        npcUtil.giveItem(player, xi.item.KODACHI_OF_TRIALS)\n                    end\n                end,\n\n                [187] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    npcUtil.giveKeyItem(player, xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH)\n                end,\n\n                [189] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH)\n                        player:delKeyItem(xi.keyItem.ANNALS_OF_TRUTH)\n                        player:delKeyItem(xi.keyItem.WEAPON_TRAINING_GUIDE)\n                        player:addLearnedWeaponskill(xi.wsUnlock.BLADE_KU)\n                        player:messageSpecial(norgID.text.BLADE_KU_LEARNED)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.LABYRINTH_OF_ONZOZO] =\n        {\n            ['qm1'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:getLocalVar('killed_wsnm') == 1 then\n                        player:setLocalVar('killed_wsnm', 0)\n                        return quest:keyItem(xi.keyItem.ANNALS_OF_TRUTH)\n                    elseif\n                        player:hasKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH) and\n                        not player:hasKeyItem(xi.keyItem.ANNALS_OF_TRUTH) and\n                        npcUtil.popFromQM(player, npc, onzozoID.mob.MEGAPOD_MEGALOPS, { hide = 0 })\n                    then\n                        return quest:messageSpecial(onzozoID.text.SENSE_OMINOUS_PRESENCE)\n                    end\n                end,\n            },\n\n            ['Megapod_Megalops'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if player:hasKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH) then\n                        player:setLocalVar('killed_wsnm', 1)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/outlands/Chasing_Dreams.lua"]={["Path"]="scripts/quests/outlands/Chasing_Dreams.lua",["SHA256"]="7c5ab84387035e1d3c91b558c58bc47cadb01e22ddc2dbdb684a5b4d1dc26ec6",["Text"]="-----------------------------------\n-- Chasing Dreams\n-----------------------------------\n-- Log ID: 5, Quest ID: 199\n-- Rabao: !zone 247\n-- Rudolfo: !pos 119 8 52\n-- Zoriboh: !pos -43 8 82\n-- Norg: !zone 252\n-- Sohyon: !pos 49 -6 14\n-- Washu: !pos 49 -6 14\n-- WASHUS_FLASK Key Item = 623\n-- Korrokola Tunnel: !zone 173\n-- Clam 1: !pos 104 -5 17\n-- Clam 2: !pos -25 -5 183\n-- Clam 3: !pos -254 -5 -56\n-- Clam 4: !pos -384 -5 53\n-- FLASK_OF_CLAM_WATER Key Item = 624\n-- Norg: !zone 252\n-- Sohyon: !pos 49 -6 14\n-- Storeroom_key Key Item = 633\n-- Gimb: !pos -6 -1 -43\n-- Port Bastok: !zone 236\n-- Kagetora: !pos -95 -2 29\n-- Eastern Gem x5: !giveitem <NAME> 1664\n-- Patient Wheel: !pos -106 5 51\n-- Selbina: !zone 248\n-- Abelard: -52 -11 -12\n-- Lufaise Meadows: !zone 24\n-- Rabao: !zone 247\n-- Zoriboh: !pos -43 8 82\n-----------------------------------\nlocal korrolokaID = zones[xi.zone.KORROLOKA_TUNNEL]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OUTLANDS, xi.quest.id.outlands.CHASING_DREAMS)\n\nquest.reward =\n{\n    item = xi.item.VENERER_RING,\n    gil  = 4000,\n}\n\nlocal handleFlask = function(player)\n    player:messageSpecial(korrolokaID.text.FILL_FLASK, xi.keyItem.WASHUS_FLASK)\n\n    if  quest:getVar(player, 'Option') == 30 then\n        player:delKeyItem(xi.keyItem.WASHUS_FLASK)\n        player:messageSpecial(korrolokaID.text.FLASK_FULL, xi.keyItem.WASHUS_FLASK)\n        npcUtil.giveKeyItem(player, xi.keyItem.FLASK_OF_CLAM_WATER)\n        quest:setVar(player, 'Prog', 4)\n\n    else\n        player:messageSpecial(korrolokaID.text.STILL_LIGHT)\n    end\nend\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            -- TODO: There is a pre-req to this quest as confirmed in captures, however the exact pre-req is unknown. WIKI indicates CoP 2-1 being started. Needs confirmation.\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.RABAO] =\n        {\n            ['Rudolfo'] = quest:progressEvent(117),\n\n            onEventFinish =\n            {\n                [117] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        -- Quest stage preceding and including getting clam water\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog <= 3\n        end,\n\n        [xi.zone.RABAO] =\n        {\n            ['Zoriboh'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        return quest:progressEvent(119)\n                    else\n                        return quest:event(120)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [119] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n\n        [xi.zone.NORG] =\n        {\n            ['Sohyon'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(209)\n                    else\n                        -- Additional Dialogue\n                        return quest:event(213)\n                    end\n                end,\n            },\n\n            ['Washu'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 2 then\n                        return quest:progressEvent(221)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [209] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n\n                [221] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.WASHUS_FLASK) -- WASHU'S FLASK Key Item = 623\n                    quest:setVar(player, 'Prog', 3)\n                end,\n            },\n        },\n\n        [xi.zone.KORROLOKA_TUNNEL] =\n        {\n            ['_4t0'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        not quest:isVarBitsSet(player, 'Option', 1) and\n                        player:hasKeyItem(xi.keyItem.WASHUS_FLASK)\n                    then\n                        quest:setVarBit(player, 'Option', 1)\n                        handleFlask(player)\n                        return quest:noAction()\n                    else\n                        return quest:messageSpecial(korrolokaID.text.CLAM_EMPTY, xi.keyItem.WASHUS_FLASK)\n                    end\n                end,\n            },\n            ['_4t1'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        not quest:isVarBitsSet(player, 'Option', 2) and\n                        player:hasKeyItem(xi.keyItem.WASHUS_FLASK)\n                    then\n                        quest:setVarBit(player, 'Option', 2)\n                        handleFlask(player)\n                        return quest:noAction()\n                    else\n                        return quest:messageSpecial(korrolokaID.text.CLAM_EMPTY, xi.keyItem.WASHUS_FLASK)\n                    end\n                end,\n            },\n            ['_4t2'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        not quest:isVarBitsSet(player, 'Option', 3) and\n                        player:hasKeyItem(xi.keyItem.WASHUS_FLASK)\n                    then\n                        quest:setVarBit(player, 'Option', 3)\n                        handleFlask(player)\n                        return quest:noAction()\n                    else\n                        return quest:messageSpecial(korrolokaID.text.CLAM_EMPTY, xi.keyItem.WASHUS_FLASK)\n                    end\n                end,\n            },\n            ['_4t3'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        not quest:isVarBitsSet(player, 'Option', 4) and\n                        player:hasKeyItem(xi.keyItem.WASHUS_FLASK)\n                    then\n                        quest:setVarBit(player, 'Option', 4)\n                        handleFlask(player)\n                        return quest:noAction()\n                    else\n                        return quest:messageSpecial(korrolokaID.text.CLAM_EMPTY, xi.keyItem.WASHUS_FLASK)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        -- Quest section suceeding having gathered the clam water\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog >= 4\n        end,\n\n        [xi.zone.NORG] =\n        {\n            ['Sohyon'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        player:hasKeyItem(xi.keyItem.FLASK_OF_CLAM_WATER) and\n                        not player:hasKeyItem(xi.keyItem.STOREROOM_KEY)\n                    then\n                        return quest:progressEvent(210)\n                    end\n                end,\n            },\n\n            ['Gimb'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.STOREROOM_KEY) then\n                        return quest:progressEvent(211, 0, xi.item.PINCH_OF_PRISM_POWDER)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [210] = function(player, csid, option, npc)\n                    player:delKeyItem(xi.keyItem.FLASK_OF_CLAM_WATER)\n                    npcUtil.giveKeyItem(player, xi.keyItem.STOREROOM_KEY)\n                end,\n\n                [211] = function(player, csid, option, npc)\n                    player:delKeyItem(xi.keyItem.STOREROOM_KEY)\n                    quest:setVar(player, 'Prog', 5)\n                end,\n            },\n        },\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Kagetora'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 5 then\n                        return quest:progressEvent(322, 0, xi.item.EASTERN_GEM)\n                    else\n                        -- Additional Dialogue\n                        return quest:event(324)\n                    end\n                end,\n            },\n\n            ['Patient_Wheel'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        quest:getVar(player, 'Prog') == 6 and\n                        npcUtil.tradeHasExactly(trade, { { xi.item.EASTERN_GEM, 5 } })\n                    then\n                        return quest:progressEvent(323)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 6 then\n                        -- Additional Dialogue\n                        return quest:event(326, 0, xi.item.EASTERN_GEM)\n                    elseif quest:getVar(player, 'Prog') > 6 then\n                        -- Additional Dialogue\n                        return quest:event(327)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [322] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 6)\n                end,\n\n                [323] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    quest:setVar(player, 'Prog', 7)\n                end,\n            },\n        },\n\n        [xi.zone.SELBINA] =\n        {\n            ['Abelard'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 7 then\n                        return quest:progressEvent(1108)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [1108] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 8)\n                end,\n            },\n        },\n\n        [xi.zone.LUFAISE_MEADOWS] =\n        {\n            onZoneIn =\n                function(player, prevZone)\n                    if quest:getVar(player, 'Prog') == 8 then\n                        return 4\n                    end\n                end,\n\n            onEventFinish =\n            {\n                [4] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 9)\n                end,\n            },\n        },\n\n        [xi.zone.RABAO] =\n        {\n            ['Zoriboh'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 9 then\n                        return quest:progressEvent(121)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [121] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:addFame(xi.fameArea.SANDORIA, 10)\n                        player:addFame(xi.fameArea.BASTOK, 10)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/outlands/Cloak_and_Dagger.lua"]={["Path"]="scripts/quests/outlands/Cloak_and_Dagger.lua",["SHA256"]="7105f982d6295ec007a6d568a53e9f7e518c11803bd502962c9cb6eedfca5603",["Text"]="-----------------------------------\n-- Cloak and Dagger\n-- Jakoh_Wahcondalo !pos 101 -16 -115 250\n-- qm1 !pos 52.8 -1 19.9 212\n-----------------------------------\nlocal kazhamID       = zones[xi.zone.KAZHAM]\nlocal gustavTunnelID = zones[xi.zone.GUSTAV_TUNNEL]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OUTLANDS, xi.quest.id.outlands.CLOAK_AND_DAGGER)\n\nquest.reward =\n{\n    fame = 20,\n    fameArea = xi.fameArea.WINDURST,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:canEquipItem(xi.item.DAGGER_OF_TRIALS, true) and\n                player:getCharSkillLevel(xi.skill.DAGGER) / 10 >= 230 and\n                not player:hasKeyItem(xi.keyItem.WEAPON_TRAINING_GUIDE)\n        end,\n\n        [xi.zone.KAZHAM] =\n        {\n            ['Jakoh_Wahcondalo'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(279):oncePerZone() -- start\n                end,\n            },\n\n            onEventFinish =\n            {\n                [279] = function(player, csid, option, npc)\n                    if\n                        player:hasItem(xi.item.DAGGER_OF_TRIALS) or\n                        npcUtil.giveItem(player, xi.item.DAGGER_OF_TRIALS)\n                    then\n                        npcUtil.giveKeyItem(player, xi.keyItem.WEAPON_TRAINING_GUIDE)\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.KAZHAM] =\n        {\n            ['Jakoh_Wahcondalo'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.ANNALS_OF_TRUTH) then\n                        return quest:progressEvent(284) -- complete\n                    elseif player:hasKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH) then\n                        return quest:event(283) -- cont 2\n                    else\n                        return quest:event(280, 0, xi.item.DAGGER_OF_TRIALS, 0, 0, player:hasItem(xi.item.DAGGER_OF_TRIALS) and 2 or 0) -- cont 1\n                    end\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, xi.item.DAGGER_OF_TRIALS) then\n                        local wsPoints = trade:getItem(0):getWeaponskillPoints()\n\n                        if wsPoints < 300 then\n                            return quest:event(281) -- unfinished weapon\n                        else\n                            return quest:progressEvent(282, 0, xi.keyItem.ANNALS_OF_TRUTH) -- finished weapon\n                        end\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [280] = function(player, csid, option, npc)\n                    if\n                        option == 1 and\n                        not player:hasItem(xi.item.DAGGER_OF_TRIALS)\n                    then\n                        npcUtil.giveItem(player, xi.item.DAGGER_OF_TRIALS)\n                    elseif option == 3 then\n                        player:delQuest(xi.questLog.OUTLANDS, xi.quest.id.outlands.CLOAK_AND_DAGGER)\n                        player:delKeyItem(xi.keyItem.WEAPON_TRAINING_GUIDE)\n                        player:delKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH)\n                    end\n                end,\n\n                [282] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    npcUtil.giveKeyItem(player, xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH)\n                end,\n\n                [284] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH)\n                        player:delKeyItem(xi.keyItem.ANNALS_OF_TRUTH)\n                        player:delKeyItem(xi.keyItem.WEAPON_TRAINING_GUIDE)\n                        player:addLearnedWeaponskill(xi.wsUnlock.EVISCERATION)\n                        player:messageSpecial(kazhamID.text.EVISCERATION_LEARNED)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.GUSTAV_TUNNEL] =\n        {\n            ['qm1'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:getLocalVar('killed_wsnm') == 1 then\n                        player:setLocalVar('killed_wsnm', 0)\n                        return quest:keyItem(xi.keyItem.ANNALS_OF_TRUTH)\n                    elseif\n                        player:hasKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH) and\n                        not player:hasKeyItem(xi.keyItem.ANNALS_OF_TRUTH) and\n                        npcUtil.popFromQM(player, npc, gustavTunnelID.mob.BARONIAL_BAT, { hide = 0 })\n                    then\n                        return quest:messageSpecial(gustavTunnelID.text.SENSE_OMINOUS_PRESENCE)\n                    end\n                end,\n            },\n\n            ['Baronial_Bat'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if player:hasKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH) then\n                        player:setLocalVar('killed_wsnm', 1)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/outlands/Divine_Might.lua"]={["Path"]="scripts/quests/outlands/Divine_Might.lua",["SHA256"]="03f8eb4d6812cb2e80af9f8c472e51a926a1f91093dd78f77578b4207de11b0b",["Text"]="-----------------------------------\n-- Divine Might\n-----------------------------------\n-- Log ID: 5, Quest ID: 163\n-- blank_divine_might : !pos -40 0 -151 178\n-- Qu'Hau Spring      : !pos 0 -29 64 122\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OUTLANDS, xi.quest.id.outlands.DIVINE_MIGHT)\n\nquest.reward =\n{\n    title = xi.title.PENTACIDE_PERPETRATOR,\n}\n\nlocal earringRewards =\n{\n    [1] = xi.item.SUPPANOMIMI,\n    [2] = xi.item.KNIGHTS_EARRING,\n    [3] = xi.item.ABYSSAL_EARRING,\n    [4] = xi.item.BEASTLY_EARRING,\n    [5] = xi.item.BUSHINOMIMI,\n}\n\nlocal onTriggerIncomplete = function(player, npc)\n    local currentMission = player:getCurrentMission(xi.mission.log_id.ZILART)\n\n    if\n        currentMission == xi.mission.id.zilart.ARK_ANGELS and\n        player:getMissionStatus(xi.mission.log_id.ZILART) == 1\n    then\n        return quest:event(54, xi.item.SHEET_OF_PARCHMENT, xi.item.BOTTLE_OF_ILLUMININK, xi.item.ARK_PENTASPHERE)\n    elseif currentMission >= xi.mission.id.zilart.ARK_ANGELS then\n        -- NOTE: In order for a player to have the appropriate KI for an event to be displayed, they will be at least\n        -- at missionStatus 1, so no need to verify greater than.\n\n        for keyItemId = xi.keyItem.SHARD_OF_APATHY, xi.keyItem.SHARD_OF_RAGE do\n            if player:hasKeyItem(keyItemId) then\n                return quest:event(56, xi.item.SHEET_OF_PARCHMENT, xi.item.BOTTLE_OF_ILLUMININK, xi.item.ARK_PENTASPHERE)\n            end\n        end\n    end\nend\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.THE_SHRINE_OF_RUAVITAU] =\n        {\n            ['blank_divine_might'] = onTriggerIncomplete,\n\n            onEventFinish =\n            {\n                [54] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n\n                [56] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.THE_SHRINE_OF_RUAVITAU] =\n        {\n            ['blank_divine_might'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(55, xi.item.SUPPANOMIMI, xi.item.KNIGHTS_EARRING, xi.item.ABYSSAL_EARRING, xi.item.BEASTLY_EARRING, xi.item.BUSHINOMIMI)\n                    else\n                        return onTriggerIncomplete(player, npc)\n                    end\n                end,\n            },\n\n            onEventUpdate =\n            {\n                [55] = function(player, csid, option, npc)\n                    if option == 2 then\n                        player:updateEvent(xi.item.SUPPANOMIMI, xi.item.KNIGHTS_EARRING, xi.item.ABYSSAL_EARRING, xi.item.BEASTLY_EARRING, xi.item.BUSHINOMIMI)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [55] = function(player, csid, option, npc)\n                    local selectedReward = earringRewards[option]\n\n                    if\n                        selectedReward and\n                        npcUtil.giveItem(player, selectedReward)\n                    then\n                        quest:complete(player)\n\n                        -- TODO: Find a way to prevent the need for using a forever charVar here.\n                        player:setCharVar('DM_Earring', selectedReward)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.ROMAEVE] =\n        {\n            ['QuHau_Spring'] =\n            {\n                onTrade = function(player, npc, trade)\n                    local vanaHour = VanadielHour()\n\n                    if\n                        (getVanadielMoonCycle() == xi.moonCycle.FULL_MOON) and\n                        (vanaHour >= 18 or vanaHour < 6) and\n                        npcUtil.tradeHasExactly(trade, { xi.item.BOTTLE_OF_ILLUMININK, xi.item.SHEET_OF_PARCHMENT })\n                    then\n                        return quest:progressEvent(7, xi.item.SHEET_OF_PARCHMENT, xi.item.BOTTLE_OF_ILLUMININK)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [7] = function(player, csid, option, npc)\n                    if npcUtil.giveItem(player, xi.item.ARK_PENTASPHERE) then\n                        player:confirmTrade()\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.LALOFF_AMPHITHEATER] =\n        {\n            onEventFinish =\n            {\n                [32001] = function(player, csid, option, npc)\n                    if player:getLocalVar('battlefieldWin') == xi.battlefield.id.DIVINE_MIGHT then\n                        quest:setVar(player, 'Prog', 1)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/outlands/Divine_Might_Repeat.lua"]={["Path"]="scripts/quests/outlands/Divine_Might_Repeat.lua",["SHA256"]="180f4c4f61042675bfd35772a19f27b49c1a82886a83706ed2710297f8a4560d",["Text"]="-----------------------------------\n-- Divine Might (Repeat)\n-----------------------------------\n-- Log ID: 5, Quest ID: 164\n-- blank_divine_might : !pos -40 0 -151 178\n-- Qu'Hau Spring      : !pos 0 -29 64 122\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OUTLANDS, xi.quest.id.outlands.DIVINE_MIGHT_REPEAT)\n\nquest.reward =\n{\n    title = xi.title.PENTACIDE_PERPETRATOR,\n}\n\nlocal earringRewards =\n{\n    [1] = xi.item.SUPPANOMIMI,\n    [2] = xi.item.KNIGHTS_EARRING,\n    [3] = xi.item.ABYSSAL_EARRING,\n    [4] = xi.item.BEASTLY_EARRING,\n    [5] = xi.item.BUSHINOMIMI,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status ~= xi.questStatus.QUEST_ACCEPTED and\n                player:hasCompletedQuest(xi.questLog.OUTLANDS, xi.quest.id.outlands.DIVINE_MIGHT)\n        end,\n\n        [xi.zone.THE_SHRINE_OF_RUAVITAU] =\n        {\n            ['blank_divine_might'] =\n            {\n                onTrigger = function(player, npc)\n                    local numEarrings = 0\n                    for itemId = xi.item.SUPPANOMIMI, xi.item.BUSHINOMIMI do\n                        if player:hasItem(itemId) then\n                            numEarrings = numEarrings + 1\n                        end\n                    end\n\n                    if numEarrings < xi.settings.main.NUMBER_OF_DM_EARRINGS then\n                        return quest:progressEvent(57, player:getCharVar('DM_Earring'))\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [57] = function(player, csid, option, npc)\n                    player:delQuest(xi.questLog.OUTLANDS, xi.quest.id.outlands.DIVINE_MIGHT_REPEAT)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.THE_SHRINE_OF_RUAVITAU] =\n        {\n            ['blank_divine_might'] =\n            {\n                onTrigger = function(player, npc)\n                    local hasMoonOre = player:hasKeyItem(xi.keyItem.MOONLIGHT_ORE)\n\n                    if quest:getVar(player, 'Prog') == 0 then\n                        if not hasMoonOre then\n                            return quest:event(58)\n                        else\n                            return quest:event(56, xi.item.SHEET_OF_PARCHMENT, xi.item.BOTTLE_OF_ILLUMININK, xi.item.ARK_PENTASPHERE)\n                        end\n                    elseif hasMoonOre then\n                        return quest:progressEvent(59)\n                    end\n                end,\n            },\n\n            onEventUpdate =\n            {\n                [59] = function(player, csid, option, npc)\n                    if option == 2 then\n                        player:updateEvent(xi.item.SUPPANOMIMI, xi.item.KNIGHTS_EARRING, xi.item.ABYSSAL_EARRING, xi.item.BEASTLY_EARRING, xi.item.BUSHINOMIMI)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [59] = function(player, csid, option, npc)\n                    local selectedReward = earringRewards[option]\n\n                    if\n                        selectedReward and\n                        npcUtil.giveItem(player, selectedReward)\n                    then\n                        quest:complete(player)\n\n                        -- TODO: Find a way to prevent the need for using a forever charVar here.\n                        player:setCharVar('DM_Earring', selectedReward)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.ROMAEVE] =\n        {\n            ['QuHau_Spring'] =\n            {\n                onTrade = function(player, npc, trade)\n                    local vanaHour = VanadielHour()\n\n                    if\n                        (getVanadielMoonCycle() == xi.moonCycle.FULL_MOON) and\n                        (vanaHour >= 18 or vanaHour < 6)\n                    then\n                        if npcUtil.tradeHasExactly(trade, { xi.item.BOTTLE_OF_ILLUMININK, xi.item.SHEET_OF_PARCHMENT }) then\n                            return quest:progressEvent(7, xi.item.SHEET_OF_PARCHMENT, xi.item.BOTTLE_OF_ILLUMININK)\n                        elseif\n                            not player:hasKeyItem(xi.keyItem.MOONLIGHT_ORE) and\n                            npcUtil.tradeHasExactly(trade, xi.item.CHUNK_OF_LIGHT_ORE)\n                        then\n                            return quest:progressEvent(8)\n                        end\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [7] = function(player, csid, option, npc)\n                    if npcUtil.giveItem(player, xi.item.ARK_PENTASPHERE) then\n                        player:confirmTrade()\n                    end\n                end,\n\n                [8] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.MOONLIGHT_ORE)\n                    player:confirmTrade()\n                end,\n            },\n        },\n\n        [xi.zone.LALOFF_AMPHITHEATER] =\n        {\n            onEventFinish =\n            {\n                [32001] = function(player, csid, option, npc)\n                    if\n                        player:getLocalVar('battlefieldWin') == xi.battlefield.id.DIVINE_MIGHT and\n                        player:hasKeyItem(xi.keyItem.MOONLIGHT_ORE)\n                    then\n                        quest:setVar(player, 'Prog', 1)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/outlands/Everyones_Grudging.lua"]={["Path"]="scripts/quests/outlands/Everyones_Grudging.lua",["SHA256"]="8693cf1b3e6913e7223140cf1d2ff9a1473b49a06b886d83be15653ce430c9d2",["Text"]="-----------------------------------\n-- Everyone's Grudging\n-- Log ID: 5, Quest ID: 4\n-- Jakoh Wahcondalo !pos 98.153 -15.000 -113.251\n-- Rancor Flame     !pos -76 16 -1\n-- Alter of Rancor  !pos 116.448 16.000 -318.659\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OUTLANDS, xi.quest.id.outlands.EVERYONES_GRUDGING)\n\nquest.reward =\n{\n    fame     = 60,\n    fameArea = xi.fameArea.WINDURST,\n    gil      = 11000,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getFameLevel(xi.fameArea.WINDURST) >= 7 and\n                player:hasCompletedQuest(xi.questLog.OUTLANDS, xi.quest.id.outlands.A_QUESTION_OF_TASTE) and\n                not xi.quest.getMustZone(player, xi.questLog.WINDURST, xi.quest.id.windurst.A_POSE_BY_ANY_OTHER_NAME) and\n                player:getCharVar('rancorCurse') == 1\n        end,\n\n        [xi.zone.KAZHAM] =\n        {\n            ['Jakoh_Wahcondalo'] = quest:progressCutscene(107, 0, xi.item.RANCOR_FLAME),\n\n            onEventFinish =\n            {\n                [107] = function(player, csid, option, npc)\n                    quest:begin(player)\n                    player:addTitle(xi.title.EXCOMMUNICATE_OF_KAZHAM)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.KAZHAM] =\n        {\n            ['Etteh_Sulaej'] = quest:event(109, 0, xi.item.RANCOR_FLAME),\n\n            ['Jakoh_Wahcondalo'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        return quest:event(108, 0, xi.item.RANCOR_FLAME)\n                    else\n                        return quest:event(110, 0, xi.item.RANCOR_FLAME)\n                    end\n                end,\n            },\n\n            ['Romaa_Mihgo'] = quest:event(276, 0, xi.item.RANCOR_FLAME),\n\n            onEventFinish =\n            {\n                [110] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n            },\n        },\n\n        [xi.zone.DEN_OF_RANCOR] =\n        {\n            ['Rancor_Torch'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        quest:setVar(player, 'Prog', 1)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/outlands/Forge_Your_Destiny.lua"]={["Path"]="scripts/quests/outlands/Forge_Your_Destiny.lua",["SHA256"]="4a1c2e7c20f019fe7c93b85f6490bf84f76a09a75b9ec01430f3dc897d1dcded",["Text"]="-----------------------------------\n-- Forge Your Destiny\n-----------------------------------\n-- Log ID: 5, Quest ID: 129\n-- Jaucribaix      : !pos 91 -7 -8 252\n-- Aeka            : !pos 4 0 -4 252\n-- Ranemaud        : !pos 15 0 23 252\n-- qm3 (Konschtat) : !pos -709 2 102 108\n-- qm2 (Zi'Tah)    : !pos 642 -5 -150 121\n-----------------------------------\nlocal konschtatID = zones[xi.zone.KONSCHTAT_HIGHLANDS]\nlocal norgID      = zones[xi.zone.NORG]\nlocal zitahID     = zones[xi.zone.THE_SANCTUARY_OF_ZITAH]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OUTLANDS, xi.quest.id.outlands.FORGE_YOUR_DESTINY)\n\nquest.reward =\n{\n    fame     = 20,\n    fameArea = xi.fameArea.NORG,\n    item     = xi.item.MUMEITO,\n    keyItem  = xi.keyItem.JOB_GESTURE_SAMURAI,\n    title    = xi.title.BUSHIDO_BLADE,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and player:getMainLvl() >= xi.settings.main.ADVANCED_JOB_LEVEL\n        end,\n\n        [xi.zone.NORG] =\n        {\n            ['Jaucribaix'] = quest:progressEvent(25, xi.item.SACRED_BRANCH, xi.item.LUMP_OF_BOMB_STEEL),\n\n            onEventFinish =\n            {\n                [25] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.KONSCHTAT_HIGHLANDS] =\n        {\n            ['qm3'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if player:checkDistance(npc) > 1.6 then\n                        return quest:messageSpecial(konschtatID.text.BLACKENED_MUST_BE_CLOSER)\n                    end\n\n                    if not npcUtil.tradeMatches(trade, { { xi.item.LUMP_OF_ORIENTAL_STEEL, 1 } }) then\n                        return quest:noAction()\n                    end\n\n                    if\n                        GetMobByID(konschtatID.mob.FORGER):isSpawned() or\n                        npc:getLocalVar('forgerNextPopAllowedTime') > GetSystemTime()\n                    then\n                        return quest:messageSpecial(konschtatID.text.BLACKENED_NOTHING_HAPPENS, xi.item.LUMP_OF_ORIENTAL_STEEL)\n                    end\n\n                    local forgerMob = SpawnMob(konschtatID.mob.FORGER)\n                    if not forgerMob then\n                        return quest:noAction()\n                    end\n\n                    forgerMob:updateClaim(player)\n                    player:tradeComplete()\n\n                    -- QM is visible, but cannot be used to spawn Forger again until two minutes have elapsed since the NM despawns.\n                    forgerMob:setLocalVar('QMID', npc:getID())\n                    forgerMob:addListener('DESPAWN', 'DESPAWN_' .. konschtatID.mob.FORGER, function(mobArg)\n                        local qmID = mobArg:getLocalVar('QMID')\n\n                        mobArg:removeListener('DESPAWN_' .. konschtatID.mob.FORGER)\n                        GetNPCByID(qmID):setLocalVar('forgerNextPopAllowedTime', GetSystemTime() + 120)\n                    end)\n\n                    return quest:messageSpecial(konschtatID.text.PLACE_BLACKENED_SPOT, xi.item.LUMP_OF_ORIENTAL_STEEL)\n                end,\n\n                onTrigger = function(player, npc)\n                    if GetMobByID(konschtatID.mob.FORGER):isSpawned() then\n                        return quest:messageSpecial(konschtatID.text.NOT_THE_TIME_FOR_THAT)\n\n                    -- This message persists even after kill, while the QM is active and quest is accepted.\n                    elseif npc:getLocalVar('forgerNextPopAllowedTime') <= GetSystemTime() then\n                        return quest:messageSpecial(konschtatID.text.BLACKENED_SHOULD_PLACE, xi.item.LUMP_OF_ORIENTAL_STEEL)\n\n                    -- Forger was killed and is still on its respawn cooldown.\n                    else\n                        return quest:messageSpecial(konschtatID.text.BLACKENED_SPOT_ON_GROUND)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.NORG] =\n        {\n            ['Aeka'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        quest:isVarBitsSet(player, 'Option', 0) and\n                        npcUtil.tradeMatches(trade, { { xi.item.CHUNK_OF_DARKSTEEL_ORE, 1 } })\n                    then\n                        return quest:progressEvent(47, 0, xi.item.LUMP_OF_ORIENTAL_STEEL, xi.item.CHUNK_OF_DARKSTEEL_ORE)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'waitTime') ~= 0 then\n                        return quest:progressEvent(50)\n                    end\n\n                    if player:findItem(xi.item.LUMP_OF_BOMB_STEEL) then\n                        return quest:progressEvent(49, xi.item.LUMP_OF_BOMB_STEEL, xi.item.LUMP_OF_ORIENTAL_STEEL)\n                    elseif not player:findItem(xi.item.LUMP_OF_ORIENTAL_STEEL) then\n                        if not quest:isVarBitsSet(player, 'Option', 0) then\n                            return quest:progressEvent(44, xi.item.LUMP_OF_BOMB_STEEL, xi.item.LUMP_OF_ORIENTAL_STEEL)\n                        else\n                            return quest:progressEvent(46, 0, xi.item.LUMP_OF_ORIENTAL_STEEL, xi.item.CHUNK_OF_DARKSTEEL_ORE)\n                        end\n                    else\n                        return quest:progressEvent(45, xi.item.LUMP_OF_BOMB_STEEL, xi.item.LUMP_OF_ORIENTAL_STEEL)\n                    end\n                end,\n            },\n\n            ['Jaucribaix'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeMatches(trade, { { xi.item.LUMP_OF_BOMB_STEEL, 1 }, { xi.item.SACRED_BRANCH, 1 } }) then\n                        return quest:progressEvent(27)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    local waitTime      = quest:getVar(player, 'waitTime')\n                    local timeRemaining = waitTime - GetSystemTime()\n\n                    if waitTime == 0 then\n                        return quest:progressEvent(26)\n                    elseif timeRemaining > 0 then\n                        -- Parameter is remaining time in Vana'diel hours.\n                        return quest:progressEvent(28, timeRemaining / 144)\n                    else\n                        return quest:progressEvent(29, xi.item.MUMEITO)\n                    end\n                end,\n            },\n\n            ['Ranemaud'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        quest:isVarBitsSet(player, 'Option', 1) and\n                        trade:getItemQty(xi.item.CHUNK_OF_GOLD_ORE) == 2 and\n                        trade:getItemQty(xi.item.CHUNK_OF_PLATINUM_ORE) == 1 and\n                        trade:getItemCount() == 3\n                    then\n                        return quest:progressEvent(43, 0, 0, xi.item.CHUNK_OF_PLATINUM_ORE, xi.item.CHUNK_OF_GOLD_ORE)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'waitTime') == 0 then\n                        if player:findItem(xi.item.SACRED_BRANCH) then\n                            return quest:progressEvent(48, xi.item.SACRED_BRANCH, xi.item.SACRED_SPRIG)\n                        elseif not player:findItem(xi.item.SACRED_SPRIG) then\n                            if not quest:isVarBitsSet(player, 'Option', 1) then\n                                return quest:progressEvent(40, xi.item.SACRED_BRANCH, xi.item.SACRED_SPRIG)\n                            else\n                                return quest:progressEvent(42, 0, xi.item.SACRED_SPRIG, xi.item.CHUNK_OF_PLATINUM_ORE, xi.item.CHUNK_OF_GOLD_ORE)\n                            end\n                        else\n                            return quest:progressEvent(41)\n                        end\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [27] = function(player, csid, option, npc)\n                    -- TODO: Add constant for Vana'diel day in seconds, this is a three game day wait.\n                    player:tradeComplete()\n                    quest:setVar(player, 'waitTime', GetSystemTime() + 10368)\n                end,\n\n                [29] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:messageSpecial(norgID.text.YOU_CAN_NOW_BECOME_A_SAMURAI, xi.item.MUMEITO)\n                        player:unlockJob(xi.job.SAM)\n                    end\n                end,\n\n                [40] = function(player, csid, option, npc)\n                    if npcUtil.giveItem(player, xi.item.SACRED_SPRIG) then\n                        quest:setVarBit(player, 'Option', 1)\n                    end\n                end,\n\n                [43] = function(player, csid, option, npc)\n                    if npcUtil.giveItem(player, xi.item.SACRED_SPRIG) then\n                        player:tradeComplete()\n                    end\n                end,\n\n                [44] = function(player, csid, option, npc)\n                    if npcUtil.giveItem(player, xi.item.LUMP_OF_ORIENTAL_STEEL) then\n                        quest:setVarBit(player, 'Option', 0)\n                    end\n                end,\n\n                [47] = function(player, csid, option, npc)\n                    if npcUtil.giveItem(player, xi.item.LUMP_OF_ORIENTAL_STEEL) then\n                        player:tradeComplete()\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.THE_SANCTUARY_OF_ZITAH] =\n        {\n            ['Guardian_Treant'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n\n            ['qm2'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        player:hasItem(xi.item.SACRED_SPRIG) and\n                        trade:getItemQty(xi.item.HATCHET) == 1 and\n                        trade:getItemCount() == 1\n                    then\n                        if\n                            GetMobByID(zitahID.mob.GUARDIAN_TREANT):isSpawned() or\n                            npc:getLocalVar('treantNextPopAllowedTime') > GetSystemTime()\n                        then\n                            return quest:messageSpecial(zitahID.text.STRANGE_FORCE_PREVENTS)\n                        else\n                            local treantMob = SpawnMob(zitahID.mob.GUARDIAN_TREANT)\n                            if not treantMob then\n                                return quest:noAction()\n                            end\n\n                            treantMob:updateClaim(player)\n                            player:tradeComplete()\n\n                            -- QM is visible, but cannot be used to spawn Guardian Treant again until ten minutes have elapsed since the NM despawns.\n                            treantMob:setLocalVar('QMID', npc:getID())\n                            treantMob:addListener('DESPAWN', 'DESPAWN_' .. zitahID.mob.GUARDIAN_TREANT, function(mobArg)\n                                local qmID = mobArg:getLocalVar('QMID')\n\n                                mobArg:removeListener('DESPAWN_' .. zitahID.mob.GUARDIAN_TREANT)\n                                GetNPCByID(qmID):setLocalVar('treantNextPopAllowedTime', GetSystemTime() + 60 * 10)\n                            end)\n\n                            return quest:messageSpecial(zitahID.text.SENSE_STRONG_EVIL_PRESENCE)\n                        end\n                    elseif\n                        trade:getItemQty(xi.item.SACRED_SPRIG) == 1 and\n                        trade:getItemCount() == 1 and\n                        quest:getVar(player, 'Prog') == 1 and\n                        npcUtil.giveItem(player, xi.item.SACRED_BRANCH)\n                    then\n                        quest:setVar(player, 'Prog', 2)\n                        player:tradeComplete()\n                        return quest:messageSpecial(zitahID.text.STRANGE_FORCE_VANISHED, xi.item.SACRED_BRANCH)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if GetMobByID(zitahID.mob.GUARDIAN_TREANT):isSpawned() then\n                        return quest:messageSpecial(zitahID.text.NOT_THE_TIME_FOR_THAT)\n                    elseif questProgress == 1 then\n                        return quest:messageSpecial(zitahID.text.NO_LONGER_SENSE_EVIL)\n                    elseif questProgress == 2 then\n                        return quest:messageSpecial(zitahID.text.NEWLY_SPROUTED_GLOWING, xi.item.SACRED_SPRIG)\n                    elseif npc:getLocalVar('treantNextPopAllowedTime') <= GetSystemTime() then\n                        return quest:messageSpecial(zitahID.text.LOOKS_LIKE_STURDY_BRANCH, xi.item.HATCHET)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/outlands/Ill_Take_the_Big_Box.lua"]={["Path"]="scripts/quests/outlands/Ill_Take_the_Big_Box.lua",["SHA256"]="1a3aae3dc36300cbf1e429bf0477dd5ca15e9153cb13fff93e355786a3a48bd9",["Text"]="-----------------------------------\n-- I'll Take the Big Box (NIN AF2)\n-----------------------------------\n-- Log ID: 5, Quest ID: 144\n-- !addquest 5 144\n-- Ryoma     : !pos -26 0 -8 252\n-- Ensetsu   : !pos 32 -7 69 236\n-- Leodarion : !pos -50 8 41 247\n-----------------------------------\n-- Leodarion finishes the trap overnight: the seance staff is handed over once the\n-- Vana'diel day has changed since the oak pole was traded.\n-- Enagakure only appears aboard the Selbina-bound ferry at night. Its spawn stays in\n-- the ship zones because the framework has no game hour handler.\n-- The completion cutscene spawns its own actors, so retail sends it with the zone's\n-- NPCs hidden: cutscene flags 0x0013.\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OUTLANDS, xi.quest.id.outlands.I_LL_TAKE_THE_BIG_BOX)\n\nquest.reward =\n{\n    fame     = 20,\n    fameArea = xi.fameArea.NORG,\n    item     = xi.item.NINJA_HAKAMA,\n}\n\nquest.sections =\n{\n    -- Section: Quest is available.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.OUTLANDS, xi.quest.id.outlands.TWENTY_IN_PIRATE_YEARS)\n        end,\n\n        [xi.zone.NORG] =\n        {\n            ['Ryoma'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        player:getMainJob() ~= xi.job.NIN or\n                        player:getMainLvl() < xi.settings.main.AF2_QUEST_LEVEL or\n                        player:needToZone()\n                    then\n                        return\n                    end\n\n                    return quest:progressEvent(135)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [135] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepted.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Ensetsu'] =\n            {\n                onTrigger = function(player, npc)\n                    local progress = quest:getVar(player, 'Prog')\n\n                    if progress == 0 then\n                        return quest:progressEvent(264)\n                    elseif progress == 1 then\n                        return quest:event(265) -- Reminder: Mitsunari's grandson lives in the Altepa Desert.\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [264] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n\n        [xi.zone.RABAO] =\n        {\n            ['Leodarion'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        quest:getVar(player, 'Prog') == 2 and\n                        npcUtil.tradeMatches(trade, { { xi.item.OAK_POLE, 1 } })\n                    then\n                        return quest:progressEvent(92)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    local progress = quest:getVar(player, 'Prog')\n\n                    if progress == 1 then\n                        return quest:progressEvent(90)\n                    elseif progress == 2 then\n                        return quest:event(91) -- Reminder: bring an oak pole.\n                    elseif progress == 3 then\n                        if VanadielUniqueDay() < quest:getVar(player, 'Timer') then\n                            return quest:event(93) -- Reminder: the trap is not finished yet.\n                        end\n\n                        return quest:progressEvent(94)\n                    elseif progress == 4 then\n                        return quest:event(95) -- Reminder: sail the Bastore Sea from east to west at night.\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [90] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n\n                [92] = function(player, csid, option, npc)\n                    player:tradeComplete()\n                    quest:setVar(player, 'Timer', VanadielUniqueDay() + 1)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n\n                [94] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.SEANCE_STAFF)\n                    quest:setVar(player, 'Prog', 4)\n                end,\n            },\n        },\n\n        [xi.zone.SELBINA] =\n        {\n            onZoneIn = function(player, prevZone)\n                if quest:getVar(player, 'Prog') == 5 then\n                    return { 1101, -1, bit.bor(xi.cutsceneFlag.RESET_CAMERA, xi.cutsceneFlag.NO_PCS, xi.cutsceneFlag.NO_NPCS) }\n                end\n            end,\n\n            onEventFinish =\n            {\n                [1101] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.SEANCE_STAFF)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.SHIP_BOUND_FOR_SELBINA] =\n        {\n            ['Enagakure'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if quest:getVar(player, 'Prog') == 4 then\n                        quest:setVar(player, 'Prog', 5)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.SHIP_BOUND_FOR_SELBINA_PIRATES] =\n        {\n            ['Enagakure'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if quest:getVar(player, 'Prog') == 4 then\n                        quest:setVar(player, 'Prog', 5)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/outlands/Its_Not_Your_Vault.lua"]={["Path"]="scripts/quests/outlands/Its_Not_Your_Vault.lua",["SHA256"]="ac8300fa1153583f62705132da75367c536c2079526fd5a1e07e6054e1a1cb10",["Text"]="-----------------------------------\n-- It's Not Your Vault\n-- https://wiki.ffo.jp/html/12512.html\n-----------------------------------\n-- Log ID: 5, Quest ID: 137\n-- Keal : !pos -5.453 0.151 -16.361 252\n-- qm3  : !pos -173.671 26.951 252.009 176\n-----------------------------------\nlocal seaSerpentID = zones[xi.zone.SEA_SERPENT_GROTTO]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OUTLANDS, xi.quest.id.outlands.ITS_NOT_YOUR_VAULT)\n\nquest.reward =\n{\n    fame     = 30,\n    fameArea = xi.fameArea.NORG,\n    item     = xi.item.SCROLL_OF_TONKO_ICHI,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getFameLevel(xi.fameArea.NORG) >= 3 and\n                player:getMainLvl() >= 5\n        end,\n\n        [xi.zone.NORG] =\n        {\n            ['Keal'] =\n            {\n                onTrigger = function(player, npc)\n                    local hasDeclined = quest:getVar(player, 'Option')\n\n                    return quest:progressEvent(36, { [0] = xi.keyItem.SEALED_IRON_BOX, [7] = hasDeclined })\n                end,\n            },\n\n            onEventFinish =\n            {\n                [36] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                    else\n                        quest:setVar(player, 'Option', 1)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.NORG] =\n        {\n            ['Keal'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.SEALED_IRON_BOX) then\n                        return quest:progressEvent(38)\n                    else\n                        return quest:event(37, xi.keyItem.MAP_OF_SEA_SERPENT_GROTTO)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [38] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.SEALED_IRON_BOX)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.SEA_SERPENT_GROTTO] =\n        {\n            ['qm3'] =\n            {\n                onTrigger = function(player, npc)\n                    if not player:hasKeyItem(xi.keyItem.SEALED_IRON_BOX) then\n                        return quest:keyItem(xi.keyItem.SEALED_IRON_BOX)\n                    end\n\n                    player:messageText(npc, seaSerpentID.text.NO_LONGER_ANYTHING_ON_FLOOR, false, 6)\n                    return quest:noAction()\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.NORG] =\n        {\n            ['Keal'] = quest:event(39):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/outlands/Like_Shining_Leggings.lua"]={["Path"]="scripts/quests/outlands/Like_Shining_Leggings.lua",["SHA256"]="d87b473bc6ca088a257d1b843d980eb4c4e68ff95ed69bb3ffc351472db94855",["Text"]="-----------------------------------\n-- Like Shining Leggings\n-----------------------------------\n-- Log ID: 5 (Outlands), Quest ID: 139\n-- Heizo : !pos -1 -5 25 252\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OUTLANDS, xi.quest.id.outlands.LIKE_SHINING_LEGGINGS)\n\nquest.reward =\n{\n    fameArea = xi.fameArea.NORG,\n    fame     = 30,\n    title    = xi.title.LOOKS_GOOD_IN_LEGGINGS,\n    item     = xi.item.SCROLL_OF_DOKUMORI_ICHI,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n            player:getFameLevel(xi.fameArea.NORG) >= 3\n        end,\n\n        [xi.zone.NORG] =\n        {\n            ['Heizo'] = quest:progressEvent(127),\n\n            onEventFinish =\n            {\n                [127] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.NORG] =\n        {\n            ['Heizo'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(128, quest:getVar(player, 'Prog'))-- Update the player on the number of Rusty Leggings they have turned in\n                end,\n\n                onTrade = function(player, npc, trade)\n                    local legging = trade:getItemQty(xi.item.RUSTY_LEGGINGS)\n                    local turnedInVar = quest:getVar(player, 'Prog')\n                    local totalLeggings = legging + turnedInVar\n\n                    if\n                        legging > 0 and\n                        legging == trade:getItemCount() -- Verifies that only Rusty Leggings are being traded\n                    then\n                        if turnedInVar + legging >= 10 then -- complete quest\n                            return quest:progressEvent(129)\n                        elseif turnedInVar <= 9 then -- turning in less than the amount needed to finish the quest\n                            player:tradeComplete()\n                            quest:setVar(player, 'Prog', totalLeggings)\n                            return quest:event(128, totalLeggings) -- Update player on number of leggings turned in\n                        end\n                    else\n                        return quest:event(128, turnedInVar) -- Update player on number of leggings turned in, but doesn't accept anything other than leggings\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [129] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:tradeComplete()\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/outlands/Like_Shining_Subligar.lua"]={["Path"]="scripts/quests/outlands/Like_Shining_Subligar.lua",["SHA256"]="56f00954551134df47398fcbf004280f6739b2121f8a8edfef529d9aed14598d",["Text"]="-----------------------------------\n-- Like Shining Subligars\n-----------------------------------\n-- Log ID: 5 (Outlands), Quest ID: 138\n-- Heiji : !pos -1 -5 25 252\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OUTLANDS, xi.quest.id.outlands.LIKE_A_SHINING_SUBLIGAR)\n\nquest.reward =\n{\n    fameArea = xi.fameArea.NORG,\n    fame     = 30,\n    title    = xi.title.LOOKS_SUBLIME_IN_A_SUBLIGAR,\n    item     = xi.item.SCROLL_OF_KURAYAMI_ICHI,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getFameLevel(xi.fameArea.NORG) >= 3\n        end,\n\n        [xi.zone.NORG] =\n        {\n            ['Heiji'] = quest:progressEvent(123),\n\n            onEventFinish =\n            {\n                [123] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.NORG] =\n        {\n            ['Heiji'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(124, quest:getVar(player, 'Prog'))-- Update the player on the number of Rusty Subligars they have turned in\n                end,\n\n                onTrade = function(player, npc, trade)\n                    local subligarsInTrade = trade:getItemQty(xi.item.RUSTY_SUBLIGAR)\n                    local subligarsStored  = quest:getVar(player, 'Prog')\n                    local subligarsTotal   = subligarsInTrade + subligarsStored\n\n                    -- No subligars in trade or items other than subligars.\n                    if\n                        subligarsInTrade == 0 or\n                        subligarsInTrade ~= trade:getItemCount()\n                    then\n                        return quest:event(124, subligarsStored)\n                    end\n\n                    -- Trade has only subligars. Check how many we have total.\n                    if subligarsTotal >= 10 then\n                        return quest:progressEvent(125) -- Complete quest\n                    else\n                        player:tradeComplete()\n                        quest:setVar(player, 'Prog', subligarsTotal)\n                        return quest:event(124, subligarsTotal)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [125] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:tradeComplete()\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/outlands/Open_Sesame.lua"]={["Path"]="scripts/quests/outlands/Open_Sesame.lua",["SHA256"]="475f239751f5b79ff5ff69865f0b1576bbff061962390fee7e8ef636a05bfeb4",["Text"]="-----------------------------------\n-- Open Sesame\n-----------------------------------\n-- Log ID: 5, Quest ID: 165\n-- Lokpix : !pos -61.942 3.949 224.900 114\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OUTLANDS, xi.quest.id.outlands.OPEN_SESAME)\n\nquest.reward =\n{\n    keyItem = xi.keyItem.LOADSTONE,\n}\n\nlocal tradeOptions =\n{\n    [1] = { xi.item.METEORITE,   1 },\n    [2] = { xi.item.SOIL_GEM,    1 },\n    [3] = { xi.item.SOIL_GEODE, 12 },\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.EASTERN_ALTEPA_DESERT] =\n        {\n            ['Lokpix'] = quest:progressEvent(20),\n\n            onEventFinish =\n            {\n                [20] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.EASTERN_ALTEPA_DESERT] =\n        {\n            ['Lokpix'] =\n            {\n                onTrade = function(player, npc, trade)\n                    for i = 1, #tradeOptions do\n                        if\n                            trade:getItemQty(tradeOptions[i][1]) == tradeOptions[i][2] and\n                            trade:getItemQty(xi.item.TREMORSTONE) == 1\n                        then\n                            return quest:progressEvent(22)\n                        end\n                    end\n\n                    return quest:event(23)\n                end,\n\n                onTrigger = function(player, npc)\n                    return quest:event(21)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [22] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:addFame(xi.fameArea.SANDORIA, 15)\n                        player:addFame(xi.fameArea.BASTOK, 15)\n                        player:tradeComplete()\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.EASTERN_ALTEPA_DESERT] =\n        {\n            ['Lokpix'] = quest:event(24):replaceDefault()\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/outlands/SAM_AF1_The_Sacred_Katana.lua"]={["Path"]="scripts/quests/outlands/SAM_AF1_The_Sacred_Katana.lua",["SHA256"]="48e2c27590c04d308940acdf354664268e2300684bff6ae5ffbf30509eb362ba",["Text"]="-----------------------------------\n-- The Sacred Katana (SAM AF1)\n-----------------------------------\n-- Log ID: 5, Quest ID: 140\n-- Jaucribaix      : !pos 91 -7 -8 252\n-- Ranemaud        : !pos 15 0 23 252\n-- qm3 (Zi'Tah)    : !pos -416 0 46 121\n-----------------------------------\nlocal zitahID = zones[xi.zone.THE_SANCTUARY_OF_ZITAH]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OUTLANDS, xi.quest.id.outlands.THE_SACRED_KATANA)\n\nquest.reward =\n{\n    fame = 20,\n    fameArea = xi.fameArea.NORG,\n    item = xi.item.MAGOROKU,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.OUTLANDS, xi.quest.id.outlands.FORGE_YOUR_DESTINY) and\n                player:getMainJob() == xi.job.SAM and\n                player:getMainLvl() >= xi.settings.main.AF1_QUEST_LEVEL\n        end,\n\n        [xi.zone.NORG] =\n        {\n            ['Jaucribaix'] = quest:progressEvent(139),\n\n            onEventFinish =\n            {\n                [139] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.NORG] =\n        {\n            ['Jaucribaix'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        player:hasKeyItem(xi.keyItem.HANDFUL_OF_CRYSTAL_SCALES) and\n                        npcUtil.tradeMatches(trade, { { xi.item.MUMEITO, 1 } })\n                    then\n                        return quest:progressEvent(141)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    return quest:event(player:findItem(xi.item.MUMEITO) and 140 or 143)\n                end,\n            },\n\n            ['Ranemaud'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        not player:findItem(xi.item.MUMEITO) and\n                        npcUtil.tradeMatches(trade, { { xi.item.GIL, 30000 } })\n                    then\n                        return quest:progressEvent(145)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    if not player:findItem(xi.item.MUMEITO) then\n                        return quest:event(144)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [139] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                    end\n                end,\n\n                [141] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:tradeComplete()\n                        player:delKeyItem(xi.keyItem.HANDFUL_OF_CRYSTAL_SCALES)\n\n                        -- Player must zone before being able to flag the next quest\n                        xi.quest.setMustZone(player, xi.questLog.OUTLANDS, xi.quest.id.outlands.YOMI_OKURI)\n                        xi.quest.setVar(player, xi.questLog.OUTLANDS, xi.quest.id.outlands.YOMI_OKURI, 'Timer', GetSystemTime() + 60) -- 1 minute wait time\n                    end\n                end,\n\n                [145] = function(player, csid, option, npc)\n                    if npcUtil.giveItem(player, xi.item.MUMEITO) then\n                        player:tradeComplete()\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.THE_SANCTUARY_OF_ZITAH] =\n        {\n            ['Isonade'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    quest:setLocalVar(player, 'Prog', 1)\n                end,\n            },\n\n            ['qm3'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        npcUtil.tradeMatches(trade, { { xi.item.SACK_OF_FISH_BAIT, 1 } }) and\n                        npcUtil.popFromQM(player, npc, zitahID.mob.ISONADE, { hide = 0 })\n                    then\n                        player:tradeComplete()\n                        return quest:messageSpecial(zitahID.text.SENSE_OF_FOREBODING)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    if\n                        quest:getLocalVar(player, 'Prog') == 1 and\n                        not player:hasKeyItem(xi.keyItem.HANDFUL_OF_CRYSTAL_SCALES)\n                    then\n                        return quest:keyItem(xi.keyItem.HANDFUL_OF_CRYSTAL_SCALES)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/outlands/SAM_AF2_Yomi_Okuri.lua"]={["Path"]="scripts/quests/outlands/SAM_AF2_Yomi_Okuri.lua",["SHA256"]="4e66fbcd82cbae55aae2059c3d81623c2de0130f38322bcbf0eeff467eae996d",["Text"]="-----------------------------------\n-- Yomi Okuri (SAM AF2)\n-----------------------------------\n-- Log ID: 5, Quest ID: 141\n-- Jaucribaix      : !pos 91 -7 -8 252\n-- Washu           : !pos 49 -6 15 252\n-- qm2 (Onzozo)    : !pos -176 10 -60 213\n-- qm3 (Valkurm)   : !pos -767 -4 192 103\n-----------------------------------\nlocal onzozoID  = zones[xi.zone.LABYRINTH_OF_ONZOZO]\nlocal valkurmID = zones[xi.zone.VALKURM_DUNES]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OUTLANDS, xi.quest.id.outlands.YOMI_OKURI)\n\nquest.reward =\n{\n    fame = 20,\n    fameArea = xi.fameArea.NORG,\n    item = xi.item.MYOCHIN_SUNE_ATE,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.OUTLANDS, xi.quest.id.outlands.THE_SACRED_KATANA) and\n                player:getMainJob() == xi.job.SAM and\n                player:getMainLvl() >= xi.settings.main.AF2_QUEST_LEVEL\n        end,\n\n        [xi.zone.NORG] =\n        {\n            ['Jaucribaix'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        quest:getMustZone(player) or\n                        GetSystemTime() < quest:getVar(player, 'Timer')\n                    then\n                        return quest:event(142)\n                    end\n\n                    return quest:progressEvent(146)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [146] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                        quest:setVar(player, 'Prog', 1)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.LABYRINTH_OF_ONZOZO] =\n        {\n            ['qm2'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        player:hasKeyItem(xi.keyItem.WASHUS_TASTY_WURST) and\n                        not GetMobByID(onzozoID.mob.UBUME):isSpawned()\n                    then\n                        return quest:progressEvent(0)\n                    elseif\n                        quest:getVar(player, 'Stage') == 1 and\n                        not player:hasKeyItem(xi.keyItem.YOMOTSU_FEATHER)\n                    then\n                        return quest:progressEvent(1)\n                    end\n                end,\n            },\n\n            ['Ubume'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if quest:getVar(player, 'Prog') <= 3 then\n                        quest:setVar(player, 'Stage', 1)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [0] = function(player, csid, option, npc)\n                    if option == 1 then\n                        player:delKeyItem(xi.keyItem.WASHUS_TASTY_WURST)\n                        SpawnMob(onzozoID.mob.UBUME):updateClaim(player)\n                    end\n                end,\n\n                [1] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.YOMOTSU_FEATHER)\n                end,\n            },\n        },\n\n        [xi.zone.NORG] =\n        {\n            ['Jaucribaix'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress <= 3 then\n                        if not player:hasKeyItem(xi.keyItem.YOMOTSU_FEATHER) then\n                            return quest:event(147)\n                        end\n\n                        return quest:progressEvent(152)\n                    elseif questProgress == 4 then\n                        if\n                            quest:getMustZone(player) or\n                            GetSystemTime() < quest:getVar(player, 'Wait')\n                        then\n                            return quest:event(153)\n                        end\n\n                        return quest:progressEvent(154)\n                    elseif player:hasKeyItem(xi.keyItem.YOMOTSU_HIRASAKA) then\n                        return quest:event(155)\n                    elseif player:hasKeyItem(xi.keyItem.FADED_YOMOTSU_HIRASAKA) then\n                        return quest:progressEvent(156)\n                    end\n                end,\n            },\n\n            ['Washu'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        quest:getVar(player, 'Stage') == 0 and\n                        not player:hasKeyItem(xi.keyItem.WASHUS_TASTY_WURST) and\n                        not player:hasKeyItem(xi.keyItem.YOMOTSU_FEATHER) and\n                        npcUtil.tradeMatches(trade, { { xi.item.HECTEYES_EYE, 1 }, { xi.item.BASTORE_SARDINE_1, 1 }, { xi.item.SLICE_OF_GIANT_SHEEP_MEAT, 1 }, { xi.item.FROST_TURNIP, 1 } })\n                    then\n                        return quest:progressEvent(150)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(148)\n                    elseif player:hasKeyItem(xi.keyItem.WASHUS_TASTY_WURST) then\n                        return quest:event(151)\n                    elseif\n                        quest:getVar(player, 'Stage') == 0 and\n                        not player:hasKeyItem(xi.keyItem.WASHUS_TASTY_WURST)\n                    then\n                        return quest:event(149)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [148] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n\n                [150] = function(player, csid, option, npc)\n                    player:tradeComplete()\n                    npcUtil.giveKeyItem(player, xi.keyItem.WASHUS_TASTY_WURST)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n\n                [152] = function(player, csid, option, npc)\n                    player:delKeyItem(xi.keyItem.YOMOTSU_FEATHER)\n                    quest:setVar(player, 'Prog', 4)\n                    quest:setMustZone(player)\n                    quest:setVar(player, 'Wait', GetSystemTime() + 60) -- 1 minute wait time\n                end,\n\n                [154] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.YOMOTSU_HIRASAKA)\n                    quest:setVar(player, 'Prog', 5)\n                end,\n\n                [156] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.FADED_YOMOTSU_HIRASAKA)\n                        xi.quest.setMustZone(player, xi.questLog.OUTLANDS, xi.quest.id.outlands.A_THIEF_IN_NORG)\n                        xi.quest.setVar(player, xi.questLog.OUTLANDS, xi.quest.id.outlands.A_THIEF_IN_NORG, 'Timer', GetSystemTime() + 60) -- 1 minute wait time\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.VALKURM_DUNES] =\n        {\n            ['Doman'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if\n                        player:hasKeyItem(xi.keyItem.YOMOTSU_HIRASAKA) and\n                        (GetMobByID(valkurmID.mob.ONRYO):isDead() or not GetMobByID(valkurmID.mob.ONRYO):isSpawned())\n                    then\n                        quest:setLocalVar(player, 'valkurmNM', 1)\n                    end\n                end,\n            },\n\n            ['Onryo'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if\n                        player:hasKeyItem(xi.keyItem.YOMOTSU_HIRASAKA) and\n                        (GetMobByID(valkurmID.mob.DOMAN):isDead() or not GetMobByID(valkurmID.mob.DOMAN):isSpawned())\n                    then\n                        quest:setLocalVar(player, 'valkurmNM', 1)\n                    end\n                end,\n            },\n\n            ['qm3'] =\n            {\n                onTrigger = function(player, npc)\n                    local vanadielHour = VanadielHour()\n                    local domanMob     = GetMobByID(valkurmID.mob.DOMAN)\n                    local onryoMob     = GetMobByID(valkurmID.mob.ONRYO)\n\n                    if\n                        player:hasKeyItem(xi.keyItem.YOMOTSU_HIRASAKA) and\n                        quest:getLocalVar(player, 'valkurmNM') == 0 and\n                        (vanadielHour >= 18 or vanadielHour < 5)\n                    then\n                        if\n                            domanMob and\n                            onryoMob and\n                            not domanMob:isSpawned() and\n                            not onryoMob:isSpawned()\n                        then\n                            return quest:progressEvent(10)\n                        else\n                            return quest:messageSpecial(valkurmID.text.WHAT_DO_YOU_THINK)\n                        end\n                    elseif\n                        quest:getLocalVar(player, 'valkurmNM') == 1 and\n                        player:hasKeyItem(xi.keyItem.YOMOTSU_HIRASAKA)\n                    then\n                        return quest:progressEvent(11)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [10] = function(player, csid, option, npc)\n                    if option == 1 then\n                        if player:checkDistance(npc) > 2 then\n                            player:messageSpecial(valkurmID.text.MUST_BE_CLOSER, xi.keyItem.YOMOTSU_HIRASAKA)\n                        elseif\n                            not GetMobByID(valkurmID.mob.ONRYO):isSpawned() and\n                            not GetMobByID(valkurmID.mob.DOMAN):isSpawned()\n                        then\n                            player:messageSpecial(valkurmID.text.SUDDEN_CHILL)\n                            SpawnMob(valkurmID.mob.DOMAN):updateClaim(player)\n                            SpawnMob(valkurmID.mob.ONRYO):updateClaim(player)\n                        end\n                    end\n                end,\n\n                [11] = function(player, csid, option, npc)\n                    if option == 0 then\n                        player:delKeyItem(xi.keyItem.YOMOTSU_HIRASAKA)\n                        npcUtil.giveKeyItem(player, xi.keyItem.FADED_YOMOTSU_HIRASAKA)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/outlands/SAM_AF3_A_Thief_in_Norg.lua"]={["Path"]="scripts/quests/outlands/SAM_AF3_A_Thief_in_Norg.lua",["SHA256"]="dd81e42dd2a43d6b9222ef0186fe9df5d9db44e814d22e4b3bfc2dde18435747",["Text"]="-----------------------------------\n-- A Thief in Norg!? (SAM AF3)\n-----------------------------------\n-- Log ID: 5, Quest ID: 142\n-- Jaucribaix      : !pos 91 -7 -8 252\n-- Sanosuke        : !pos -63 7 0 246\n-- Phoochuchu      : !pos -4 -4 69 249\n-- _6i8 (Door)     : !pos 70 7 2 234\n-----------------------------------\nlocal waughroonID = zones[xi.zone.WAUGHROON_SHRINE]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OUTLANDS, xi.quest.id.outlands.A_THIEF_IN_NORG)\n\nquest.reward =\n{\n    fame = 20,\n    fameArea = xi.fameArea.NORG,\n    item = xi.item.MYOCHIN_KABUTO,\n    title = xi.title.PARAGON_OF_SAMURAI_EXCELLENCE,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.OUTLANDS, xi.quest.id.outlands.YOMI_OKURI) and\n                player:getMainJob() == xi.job.SAM and\n                player:getMainLvl() >= xi.settings.main.AF3_QUEST_LEVEL\n        end,\n\n        [xi.zone.NORG] =\n        {\n            ['Jaucribaix'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        quest:getMustZone(player) or\n                        GetSystemTime() < quest:getVar(player, 'Timer')\n                    then\n                        return quest:event(157)\n                    end\n\n                    return quest:progressEvent(158)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [158] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                        quest:setVar(player, 'Prog', 1)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.BASTOK_MINES] =\n        {\n            ['_6i8'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 3 then\n                        return quest:progressEvent(186)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [186] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 4)\n                end,\n            },\n        },\n\n        [xi.zone.MHAURA] =\n        {\n            ['Phoochuchu'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 2 then\n                        return quest:progressEvent(301)\n                    elseif questProgress == 3 then\n                        return quest:event(303)\n                    elseif questProgress >= 4 then\n                        return quest:event(302)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [301] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n            },\n        },\n\n        [xi.zone.NORG] =\n        {\n            ['Jaucribaix'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        player:hasKeyItem(xi.keyItem.CHARRED_HELM) and\n                        npcUtil.tradeMatches(trade, { { xi.item.SPOOL_OF_GOLD_THREAD, 1 } })\n                    then\n                        return quest:progressEvent(162)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress <= 4 then\n                        return quest:event(159)\n                    elseif questProgress == 5 then\n                        return quest:progressEvent(166)\n                    elseif questProgress == 6 then\n                        if player:findItem(xi.item.BANISHING_CHARM) then\n                            return quest:event(167)\n                        end\n\n                        return quest:progressEvent(168)\n                    elseif questProgress == 7 then\n                        return quest:progressEvent(160)\n                    elseif questProgress == 8 then\n                        return quest:event(161)\n                    elseif questProgress == 9 then\n                        if\n                            quest:getMustZone(player) or\n                            GetSystemTime() < quest:getVar(player, 'Wait')\n                        then\n                            return quest:event(163)\n                        end\n\n                        return quest:progressEvent(164)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [160] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 8)\n                end,\n\n                [162] = function(player, csid, option, npc)\n                    player:tradeComplete()\n                    player:delKeyItem(xi.keyItem.CHARRED_HELM)\n                    quest:setVar(player, 'Prog', 9)\n                    quest:setMustZone(player)\n                    quest:setVar(player, 'Wait', GetSystemTime() + 60) -- 1 minute wait time\n                end,\n\n                [164] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n\n                [166] = function(player, csid, option, npc)\n                    if npcUtil.giveItem(player, xi.item.BANISHING_CHARM) then\n                        quest:setVar(player, 'Prog', 6)\n                    end\n                end,\n\n                [168] = function(player, csid, option, npc)\n                    npcUtil.giveItem(player, xi.item.BANISHING_CHARM)\n                end,\n            },\n        },\n\n        [xi.zone.PORT_JEUNO] =\n        {\n            ['Sanosuke'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 1 then\n                        return quest:progressEvent(304)\n                    elseif questProgress == 2 then\n                        return quest:event(305)\n                    elseif questProgress >= 3 then\n                        return quest:event(306)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [304] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n            },\n        },\n\n        [xi.zone.WAUGHROON_SHRINE] =\n        {\n            onZoneIn = function(player, prevZone)\n                if quest:getVar(player, 'Prog') == 4 then\n                    return 2\n                end\n            end,\n\n            onEventFinish =\n            {\n                [2] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 5)\n                end,\n\n                [32001] = function(player, csid, option, npc)\n                    if player:getLocalVar('battlefieldWin') == xi.battlefield.id.THIEF_IN_NORG then\n                        player:messageSpecial(waughroonID.text.CHARM_DAMAGED, xi.keyItem.CHARRED_HELM, xi.item.BANISHING_CHARM)\n                        player:addKeyItem(xi.keyItem.CHARRED_HELM)\n                        quest:setVar(player, 'Prog', 7)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.NORG] =\n        {\n            ['Jaucribaix'] = quest:event(165):replaceDefault()\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/outlands/Secret_of_the_Damp_Scroll.lua"]={["Path"]="scripts/quests/outlands/Secret_of_the_Damp_Scroll.lua",["SHA256"]="24e33c3f2e85a167e4fdd032265a26ddd14c21f2cc37fe6b566956d850df9106",["Text"]="-----------------------------------\n-- Secret of the Damp Scroll\n-----------------------------------\n-- Log ID: 5, Quest ID: 135\n-- Shivivi     : !pos 68.729 -6.281 -6.432 252\n-- Hot Springs : !pos 444 -37 -18 139\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OUTLANDS, xi.quest.id.outlands.SECRET_OF_THE_DAMP_SCROLL)\n\nquest.reward =\n{\n    fame     = 30,\n    fameArea = xi.fameArea.NORG,\n    item     = xi.item.SCROLL_OF_JUBAKU_ICHI,\n    title    = xi.title.CRACKER_OF_THE_SECRET_CODE,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getFameLevel(xi.fameArea.NORG) >= 3 and\n                player:getMainLvl() >= 10 and\n                player:hasItem(xi.item.DAMP_SCROLL)\n        end,\n\n        [xi.zone.NORG] =\n        {\n            ['Shivivi'] = quest:progressEvent(31, xi.item.DAMP_SCROLL),\n\n            onEventFinish =\n            {\n                [31] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.NORG] =\n        {\n            ['Shivivi'] = quest:event(32),\n        },\n\n        [xi.zone.HORLAIS_PEAK] =\n        {\n            ['Hot_Springs'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, xi.item.DAMP_SCROLL) then\n                        return quest:progressEvent(2, xi.item.DAMP_SCROLL)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [2] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:confirmTrade()\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/outlands/Soul_Searching.lua"]={["Path"]="scripts/quests/outlands/Soul_Searching.lua",["SHA256"]="980a9e7d0a7597efb204a13b1bc2b59c5f28184d701fb22c6009a748f7e4a080",["Text"]="-----------------------------------\n-- Soul Searching\n-----------------------------------\n-- Log ID: 5, Quest ID: 162\n-- Cermet Headstone : !pos 235 0 280 121\n-----------------------------------\nlocal zitahID = zones[xi.zone.THE_SANCTUARY_OF_ZITAH]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OUTLANDS, xi.quest.id.outlands.SOUL_SEARCHING)\n\nquest.reward =\n{\n    item  = xi.item.BAT_EARRING,\n    title = xi.title.GUIDER_OF_SOULS_TO_THE_SANCTUARY,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.THE_SANCTUARY_OF_ZITAH] =\n        {\n            ['Cermet_Headstone'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.PRISMATIC_FRAGMENT) then\n                        return quest:progressEvent(202, xi.keyItem.PRISMATIC_FRAGMENT)\n                    else\n                        return quest:messageSpecial(zitahID.text.AIR_REMAINS_STAGNANT)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [202] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/outlands/Stop_Your_Whining.lua"]={["Path"]="scripts/quests/outlands/Stop_Your_Whining.lua",["SHA256"]="c8d1a7a2b38d557e33b2ff136f0595f0f28461ace72bae2aeee14b2833cef2c7",["Text"]="-----------------------------------\n-- Stop Your Whining\n-----------------------------------\n-- Log ID: 5, Quest ID: 132\n-- Washu : !pos 49 -6 15 252\n-- qm2   : !pos -94.073 -0.999 22.295 124\n-----------------------------------\nlocal yhoatorID = zones[xi.zone.YHOATOR_JUNGLE]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OUTLANDS, xi.quest.id.outlands.STOP_YOUR_WHINING)\n\nquest.reward =\n{\n    item = xi.item.SCROLL_OF_HOJO_ICHI,\n    fameArea = xi.fameArea.NORG,\n    fame = 40,\n    title = xi.title.APPRENTICE_SOMMELIER,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getFameLevel(xi.fameArea.NORG) >= 4 and\n                player:getMainLvl() >= 10\n        end,\n\n        [xi.zone.NORG] =\n        {\n            ['Washu'] = quest:progressEvent(21),\n\n            onEventFinish =\n            {\n                [21] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                        npcUtil.giveKeyItem(player, xi.keyItem.EMPTY_BARREL)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.NORG] =\n        {\n            ['Washu'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.EMPTY_BARREL) then\n                        return quest:progressEvent(22)\n                    elseif player:hasKeyItem(xi.keyItem.BARREL_OF_OPO_OPO_BREW) then\n                        return quest:progressEvent(23)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [23] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.BARREL_OF_OPO_OPO_BREW)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.YHOATOR_JUNGLE] =\n        {\n            ['qm2'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.EMPTY_BARREL) then\n                        player:messageSpecial(yhoatorID.text.TREE_CHECK)\n                        player:delKeyItem(xi.keyItem.EMPTY_BARREL)\n                        return quest:keyItem(xi.keyItem.BARREL_OF_OPO_OPO_BREW)\n                    elseif player:hasKeyItem(xi.keyItem.BARREL_OF_OPO_OPO_BREW) then\n                        return quest:messageSpecial(yhoatorID.text.TREE_FULL)\n                    end\n                end,\n            }\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.NORG] =\n        {\n            ['Washu'] = quest:event(24):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/outlands/The_Kuftal_Tour.lua"]={["Path"]="scripts/quests/outlands/The_Kuftal_Tour.lua",["SHA256"]="314219282adb8798914341dc56b2d0cf10186b1b5b0652e691f658106ce3a8e1",["Text"]="-----------------------------------\n-- The Kuftal Tour\n-----------------------------------\n-- Log ID : 5, Quest ID: 195\n-- Datta  : !pos -24.768 8.324 70.722 247\n-- qm5    : !pos -29.195 -22.159 -183.716 174\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OUTLANDS, xi.quest.id.outlands.THE_KUFTAL_TOUR)\n\nquest.reward =\n{\n    gil   = 8000,\n    title = xi.title.KUFTAL_TOURIST,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.BASTOK, xi.quest.id.bastok.THE_GUSTABERG_TOUR) and\n                player:getFameLevel(xi.fameArea.SELBINA_RABAO) >= 3\n        end,\n\n        [xi.zone.RABAO] =\n        {\n            ['Datta'] = quest:progressEvent(74),\n\n            onEventFinish =\n            {\n                [74] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.KUFTAL_TUNNEL] =\n        {\n            ['qm5'] =\n            {\n                onTrigger = function(player, npc)\n                    local flag = true\n\n                    for _, member in pairs(player:getAlliance()) do\n                        if\n                            member:getMainLvl() > 40 or\n                            member:checkDistance(player) > 15\n                        then\n                            flag = false\n                        end\n                    end\n\n                    if flag and #player:getParty() > 1 then\n                        return quest:progressEvent(14)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [14] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n\n        [xi.zone.RABAO] =\n        {\n            ['Datta'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(75)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [75] = function(player, csid, option, npc)\n                    quest:complete(player)\n                    player:addFame(xi.fameArea.SANDORIA, 10)\n                    player:addFame(xi.fameArea.BASTOK, 10)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/outlands/The_Missing_Piece.lua"]={["Path"]="scripts/quests/outlands/The_Missing_Piece.lua",["SHA256"]="9d5d07979f84afd8d2fc65e0f952f2210123a2759330565c49177ac40c407a1f",["Text"]="-----------------------------------\n-- The Missing Piece\n-----------------------------------\n-- !addquest 5 193\n-- Alfesar : !pos 23.193 8.818 38.985\n-- qm5\n    -- Possible Positions:\n        -- !pos 770, 0, -419\n        -- !pos 657, 0, -537\n        -- !pos 749, 0, -573\n        -- !pos 451, -16, -739\n        -- !pos 787, -16, -819\n-- Charlaimagnat : !pos 124.560 6.500 111.787\n-----------------------------------\nlocal rabaoID = zones[xi.zone.RABAO]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OUTLANDS, xi.quest.id.outlands.THE_MISSING_PIECE)\n\nlocal positionTable =\n{\n    [1] = { 770,   0,  -419 },\n    [2] = { 657,   0,  -537 },\n    [3] = { 759,   0,  -573 },\n    [4] = { 451, -16,  -739 },\n    [5] = { 787, -16,  -819 },\n}\n\nquest.reward =\n{\n    item = xi.item.SCROLL_OF_TELEPORT_ALTEP,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getFameLevel(xi.fameArea.SELBINA_RABAO) >= 4 and\n                player:getMainLvl() >= 10\n        end,\n\n        [xi.zone.RABAO] =\n        {\n            ['Alfesar'] = quest:progressEvent(6, xi.keyItem.ANCIENT_TABLET_FRAGMENT),\n\n            onEventFinish =\n            {\n                [6] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.RABAO] =\n        {\n            ['Alfesar'] =\n            {\n                onTrigger = function(player, npc)\n                    local progress = quest:getVar(player, 'Prog')\n\n                    if progress == 0 then\n                        return quest:event(7, xi.keyItem.ANCIENT_TABLET_FRAGMENT) -- Reminder to get KI\n                    elseif progress == 1 then\n                        return quest:progressEvent(8, xi.keyItem.ANCIENT_TABLET_FRAGMENT, xi.keyItem.TABLET_OF_ANCIENT_MAGIC, xi.keyItem.LETTER_FROM_ALFESAR) -- Player has returned with KI\n                    elseif progress == 2 then\n                        return quest:event(9, 0, xi.keyItem.TABLET_OF_ANCIENT_MAGIC) -- Reminder to go to Sandy\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [8] = function(player, csid, option, npc)\n                    player:delKeyItem(xi.keyItem.ANCIENT_TABLET_FRAGMENT)\n                    player.addKeyItem(player, xi.keyItem.TABLET_OF_ANCIENT_MAGIC)\n                    player.addKeyItem(player, xi.keyItem.LETTER_FROM_ALFESAR)\n                    quest:setVar(player, 'Prog', 2)\n                    player:messageSpecial(rabaoID.text.ACCEPTED_KEYITEM, 0, xi.keyItem.TABLET_OF_ANCIENT_MAGIC, xi.keyItem.LETTER_FROM_ALFESAR)\n                end,\n            },\n        },\n\n        [xi.zone.QUICKSAND_CAVES] =\n        {\n            ['qm5'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        quest:setVar(player, 'Prog', 1)\n                        local newPosition = npcUtil.pickNewPosition(npc:getID(), positionTable)\n                        npc:setPos(newPosition.x, newPosition.y, newPosition.z)\n                        return quest:keyItem(xi.keyItem.ANCIENT_TABLET_FRAGMENT)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.NORTHERN_SAN_DORIA] =\n        {\n            ['Charlaimagnat'] =\n            {\n                onTrigger = function(player, npc)\n                    local progress = quest:getVar(player, 'Prog')\n\n                    if progress == 2 then\n                        return quest:progressEvent(703) -- Player has turned in the KIs from Alfesar\n                    elseif\n                        progress == 3 and\n                        GetSystemTime() < quest:getVar(player, 'Wait')\n                    then\n                        return quest:event(704) -- Player has not finished the wait\n                    elseif\n                        progress == 3 and\n                        GetSystemTime() >= quest:getVar(player, 'Wait')\n                    then\n                        return quest:progressEvent(705) -- Player has finished the wait. Quest finished\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [703] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Wait', GetSystemTime() + 60)\n                    player:addTitle(xi.title.ACQUIRER_OF_ANCIENT_ARCANUM)\n                    player:delKeyItem(xi.keyItem.TABLET_OF_ANCIENT_MAGIC)\n                    player:delKeyItem(xi.keyItem.LETTER_FROM_ALFESAR)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n\n                [705] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:addFame(xi.fameArea.SANDORIA, 20)\n                        player:addFame(xi.fameArea.BASTOK, 20)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.RABAO] =\n        {\n            ['Alfesar'] = quest:event(11):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/outlands/The_Potential_Within.lua"]={["Path"]="scripts/quests/outlands/The_Potential_Within.lua",["SHA256"]="54964f60fe9a4b90f7e15330a75e9811f061e23babf450a11b329bb9e509f298",["Text"]="-----------------------------------\n-- The Potential Within\n-- Jaucribaix !pos 91 -7 -8 252\n-- qm3 !pos 200 11 99 174\n-----------------------------------\nlocal norgID         = zones[xi.zone.NORG]\nlocal kuftalTunnelID = zones[xi.zone.KUFTAL_TUNNEL]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OUTLANDS, xi.quest.id.outlands.THE_POTENTIAL_WITHIN)\n\nquest.reward =\n{\n    fame = 20,\n    fameArea = xi.fameArea.NORG,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:canEquipItem(xi.item.TACHI_OF_TRIALS, true) and\n                player:getCharSkillLevel(xi.skill.GREAT_KATANA) / 10 >= 250 and\n                not player:hasKeyItem(xi.keyItem.WEAPON_TRAINING_GUIDE)\n        end,\n\n        [xi.zone.NORG] =\n        {\n            ['Jaucribaix'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(178):oncePerZone() -- start\n                end,\n            },\n\n            onEventFinish =\n            {\n                [178] = function(player, csid, option, npc)\n                    if\n                        option == 1 and\n                        (player:hasItem(xi.item.TACHI_OF_TRIALS) or npcUtil.giveItem(player, xi.item.TACHI_OF_TRIALS))\n                    then\n                        npcUtil.giveKeyItem(player, xi.keyItem.WEAPON_TRAINING_GUIDE)\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.NORG] =\n        {\n            ['Jaucribaix'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.ANNALS_OF_TRUTH) then\n                        return quest:progressEvent(183) -- complete\n                    elseif player:hasKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH) then\n                        return quest:event(182) -- cont 2\n                    else\n                        return quest:event(179, player:hasItem(xi.item.TACHI_OF_TRIALS) and 1 or 0) -- cont 1\n                    end\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, xi.item.TACHI_OF_TRIALS) then\n                        local wsPoints = trade:getItem(0):getWeaponskillPoints()\n\n                        if wsPoints < 300 then\n                            return quest:event(180) -- unfinished weapon\n                        else\n                            return quest:progressEvent(181) -- finished weapon\n                        end\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [179] = function(player, csid, option, npc)\n                    if option == 2 then\n                        player:delQuest(xi.questLog.OUTLANDS, xi.quest.id.outlands.THE_POTENTIAL_WITHIN)\n                        player:delKeyItem(xi.keyItem.WEAPON_TRAINING_GUIDE)\n                        player:delKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH)\n                    elseif not player:hasItem(xi.item.TACHI_OF_TRIALS) then\n                        npcUtil.giveItem(player, xi.item.TACHI_OF_TRIALS)\n                    end\n                end,\n\n                [181] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    npcUtil.giveKeyItem(player, xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH)\n                end,\n\n                [183] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH)\n                        player:delKeyItem(xi.keyItem.ANNALS_OF_TRUTH)\n                        player:delKeyItem(xi.keyItem.WEAPON_TRAINING_GUIDE)\n                        player:addLearnedWeaponskill(xi.wsUnlock.TACHI_KASHA)\n                        player:messageSpecial(norgID.text.TACHI_KASHA_LEARNED)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.KUFTAL_TUNNEL] =\n        {\n            ['qm3'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:getLocalVar('killed_wsnm') == 1 then\n                        player:setLocalVar('killed_wsnm', 0)\n                        return quest:keyItem(xi.keyItem.ANNALS_OF_TRUTH)\n                    elseif\n                        player:hasKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH) and\n                        not player:hasKeyItem(xi.keyItem.ANNALS_OF_TRUTH) and\n                        npcUtil.popFromQM(player, npc, kuftalTunnelID.mob.KETTENKAEFER, { hide = 0 })\n                    then\n                        return quest:messageSpecial(kuftalTunnelID.text.SENSE_OMINOUS_PRESENCE)\n                    end\n                end,\n            },\n\n            ['Kettenkaefer'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if player:hasKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH) then\n                        player:setLocalVar('killed_wsnm', 1)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/outlands/The_Sahagins_Stash.lua"]={["Path"]="scripts/quests/outlands/The_Sahagins_Stash.lua",["SHA256"]="b989b2ef8836fb977758c3faf005efa4a887a94a13c86a8e39d1ab6687bd1561",["Text"]="-----------------------------------\n-- The Sahagin's Stash\n-----------------------------------\n-- Log ID: 5, Quest ID: 135\n-- Laisrean : !pos -2.251 -1 21.654 252\n-- qm2      : !pos 295.276 27.129 213.043 176\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OUTLANDS, xi.quest.id.outlands.THE_SAHAGINS_STASH)\n\nquest.reward =\n{\n    fame     = 40,\n    fameArea = xi.fameArea.NORG,\n    item     = xi.item.SCROLL_OF_UTSUSEMI_ICHI,\n    title    = xi.title.TREASURE_HOUSE_RANSACKER,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getFameLevel(xi.fameArea.NORG) >= 4 and\n                player:getMainLvl() >= 5\n        end,\n\n        [xi.zone.NORG] =\n        {\n            ['Laisrean'] =\n            {\n                onTrigger = function(player, npc)\n                    local hasDeclined = quest:getVar(player, 'Option')\n\n                    return quest:progressEvent(33, { [7] = hasDeclined })\n                end,\n            },\n\n            onEventFinish =\n            {\n                [33] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                    else\n                        quest:setVar(player, 'Option', 1)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.NORG] =\n        {\n            ['Laisrean'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.SEA_SERPENT_STATUE) then\n                        return quest:progressEvent(35, xi.keyItem.SEA_SERPENT_STATUE)\n                    else\n                        return quest:event(34)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [35] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.SEA_SERPENT_STATUE)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.SEA_SERPENT_GROTTO] =\n        {\n            ['qm2'] =\n            {\n                onTrigger = function(player, npc)\n                    if not player:hasKeyItem(xi.keyItem.SEA_SERPENT_STATUE) then\n                        return quest:progressEvent(1)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [1] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.SEA_SERPENT_STATUE)\n                end,\n            },\n        },\n\n    },\n}\n\nreturn quest\n"}};
